+package com.example;
+
+import com.microsoft.playwright.*;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT,
+        properties = {"vaadin.launch-browser=false", "vaadin.productionMode=true", "vaadin.eagerServerLoad=true"})
+class ContactBrowserTest {
+    // The project deliberately skips build-frontend. Serve the pinned, locally
+    // installed bundle for this test without invoking Node or fetching assets.
+    static {
+        try {
+            var root = java.nio.file.Path.of(ContactBrowserTest.class.getProtectionDomain()
+                    .getCodeSource().getLocation().toURI());
+            var repository = java.nio.file.Path.of(System.getProperty("maven.repo.local",
+                    System.getProperty("user.home") + "/.m2/repository"));
+            try (var jar = new java.util.jar.JarFile(repository.resolve(
+                    "com/vaadin/vaadin-prod-bundle/25.3.2/vaadin-prod-bundle-25.3.2.jar").toFile())) {
+                for (var entry : java.util.Collections.list(jar.entries())) {
+                    String path = entry.getName();
+                    String destination = null;
+                    if (path.startsWith("vaadin-prod-bundle/webapp/")) {
+                        destination = "META-INF/VAADIN/webapp/" + path.substring("vaadin-prod-bundle/webapp/".length());
+                    } else if (path.startsWith("vaadin-prod-bundle/config/")) {
+                        destination = "META-INF/VAADIN/config/" + path.substring("vaadin-prod-bundle/config/".length());
+                    }
+                    if (destination != null && !entry.isDirectory()) {
+                        var output = root.resolve(destination);
+                        java.nio.file.Files.createDirectories(output.getParent());
+                        try (var input = jar.getInputStream(entry)) {
+                            java.nio.file.Files.copy(input, output, java.nio.file.StandardCopyOption.REPLACE_EXISTING);
+                        }
+                    }
+                }
+            }
+        } catch (Exception exception) {
+            throw new ExceptionInInitializerError(exception);
+        }
+    }
+
+    @LocalServerPort int port;
+
+    @Test void sendsAndProtectsDraftInBrowser() {
+        try (Playwright playwright = Playwright.create(new Playwright.CreateOptions().setEnv(java.util.Map.of("PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD", "1")));
+             Browser browser = playwright.chromium().launch(new BrowserType.LaunchOptions().setHeadless(true))) {
+            Page page = browser.newPage();
+            page.navigate("http://localhost:" + port + "/contact");
+            Locator send = page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                    new Page.GetByRoleOptions().setName("Send").setExact(true));
+            assertThat(send).isEnabled();
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Ada");
+            page.getByLabel("Phone", new Page.GetByLabelOptions().setExact(true)).fill("123");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).fill("Hello from browser");
+            page.getByLabel("Message", new Page.GetByLabelOptions().setExact(true)).press("Enter");
+            assertThat(send).isDisabled();
+            assertThat(page.locator("vaadin-grid")).containsText("Hello from browser");
+            page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true)).fill("Draft");
+            assertThat(send).isEnabled();
+            page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                    new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                    new Page.GetByRoleOptions().setName("Keep editing")).click();
+            assertThat(page.getByLabel("Name", new Page.GetByLabelOptions().setExact(true))).hasValue("Draft");
+            page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                    new Page.GetByRoleOptions().setName("About")).click();
+            page.getByRole(com.microsoft.playwright.options.AriaRole.BUTTON,
+                    new Page.GetByRoleOptions().setName("Discard").setExact(true)).click();
+            assertThat(page.locator("h1")).hasText("About");
+            page.navigate("http://localhost:" + port + "/contact");
+            assertThat(page.locator("vaadin-grid")).containsText("Hello from browser");
+        }
+    }
+}
