+package com.example;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.*;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import static org.junit.jupiter.api.Assertions.*;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+    @BeforeEach void open() { navigate(ContactView.class); }
+    TextField name() { return find(TextField.class).withLabel("Name").single(); }
+    TextField phone() { return find(TextField.class).withLabel("Phone").single(); }
+    EmailField email() { return find(EmailField.class).single(); }
+    TextArea message() { return find(TextArea.class).single(); }
+    Button send() { return find(Button.class).withText("Send").single(); }
+    void click(String text) { test(find(Button.class).withText(text).single()).click(); }
+    int rows() { return find(Grid.class).single().getListDataView().getItemCount(); }
+
+    @Test void validatesWithoutSendingOrClearing() {
+        assertTrue(send().isEnabled());
+        click("Send");
+        assertEquals("Name is required", name().getErrorMessage());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertEquals("Message is required", message().getErrorMessage());
+        assertTrue(name().isInvalid());
+        assertTrue(email().isInvalid());
+        assertTrue(message().isInvalid());
+        name().setValue("Ada");
+        email().setValue("invalid");
+        phone().setValue("123");
+        message().setValue("x".repeat(501));
+        click("Send");
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertEquals("Message must be at most 500 characters", message().getErrorMessage());
+        assertEquals(501, message().getValue().length());
+        assertEquals(0, rows());
+        assertFalse(find(Notification.class).exists());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test void sendsByClickAndEnterAndRetainsHistory() {
+        name().setValue("Ada");
+        phone().setValue("123");
+        message().setValue("First");
+        click("Send");
+        assertFalse(send().isEnabled());
+        assertTrue(name().isEmpty() && phone().isEmpty() && email().isEmpty() && message().isEmpty());
+        assertTrue(find(Notification.class).exists());
+        assertEquals(1, rows());
+        name().setValue("Grace");
+        assertTrue(send().isEnabled());
+        email().setValue("grace@example.com");
+        message().setValue("x".repeat(500));
+        fireShortcut(Key.ENTER);
+        assertEquals(2, rows());
+        assertFalse(send().isEnabled());
+        SentMessages.Message newest = (SentMessages.Message) find(Grid.class).single().getListDataView().getItem(0);
+        assertEquals("Grace", newest.name());
+        UI.getCurrent().navigate("about");
+        assertInstanceOf(AboutView.class, getCurrentView());
+        assertFalse(find(Dialog.class).exists());
+        navigate(ContactView.class);
+        assertEquals(2, rows());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test void protectsDraftOnAnyNavigation() {
+        phone().setValue(" ");
+        UI.getCurrent().navigate("about");
+        assertTrue(find(Dialog.class).single().isOpened());
+        click("Keep editing");
+        assertInstanceOf(ContactView.class, getCurrentView());
+        assertEquals(" ", phone().getValue());
+        UI.getCurrent().navigate("about");
+        click("Discard");
+        assertInstanceOf(AboutView.class, getCurrentView());
+        navigate(ContactView.class);
+        assertTrue(phone().isEmpty());
+    }
+}
